using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEngine;
namespace RoadRush.Editor
{
    public static class BuildingKindVerification
    {
        [Serializable] sealed class BuildingList{public GeoBuilding[] buildings;}
        static string root;static int checks;static readonly List<string> warnings=new List<string>();
        static void Check(bool ok,string text){if(!ok)throw new Exception("BUILDING KIND FAIL: "+text);checks++;Debug.Log("BUILDING KIND PASS: "+text);}
        static void Warn(string text,string trace,LogType type){if(type==LogType.Warning)warnings.Add(text);}
        static GeoRegion Fixture()=>new GeoRegion{id="building-kind-fixture",name="Building kind fixture",preparedWidths=true,latitude=51.6707,longitude=-3.1365,minX=-1500,minZ=-1500,width=3000,depth=3000,nx=2,nz=2,heights=new[]{2f,2f,2f,2f},landNx=2,landNz=2,landCover=new int[4],roads=new[]{new GeoRoad{id="fixture-road",start="a",end="b",width=10,limit=30,points=new[]{new Vector3(-1400,0,0),new Vector3(1400,0,0)}}},waters=Array.Empty<GeoWater>(),areas=Array.Empty<GeoArea>(),buildings=Array.Empty<GeoBuilding>(),route=new[]{new Vector3(-100,0,0),new Vector3(100,0,0)}};
        static string CopyPack(string folder,string source,Action<JObject,JObject> edit=null)
        {
            Directory.CreateDirectory(folder);if(edit==null){foreach(string name in new[]{"buildings-pack.json","buildings.json"})File.Copy(Path.Combine(source,name),Path.Combine(folder,name),true);return folder;}var meta=JObject.Parse(File.ReadAllText(Path.Combine(source,"buildings-pack.json")));var data=JObject.Parse(File.ReadAllText(Path.Combine(source,"buildings.json")));edit?.Invoke(meta,data);string payload=Path.Combine(folder,"buildings.json");File.WriteAllText(payload,data.ToString(Newtonsoft.Json.Formatting.None));meta["bytes"]=new FileInfo(payload).Length;meta["sha256"]=RoadRush.Core.DataPackageRules.HashFile(payload);File.WriteAllText(Path.Combine(folder,"buildings-pack.json"),meta.ToString());return folder;
        }
        static void RejectedKind(string name,JToken value,bool remove=false)
        {
            string folder=CopyPack(Path.Combine(root,name),"/private/tmp/RoadRushDetailCompiled/PantsideBuildingsV2",(m,d)=>{if(remove)((JArray)d["buildings"])[1]["kind"]=null;else ((JArray)d["buildings"])[1]["kind"]=value;});var region=Fixture();string before=JsonUtility.ToJson(region);bool ok=new DetailBuildingPack(folder).ApplySafely(region);Check(!ok&&JsonUtility.ToJson(region)==before,"invalid "+name+" rejects entire payload before buildings or attribution mutate");
        }
        public static void Run()
        {
            try
            {
                root=Path.GetFullPath("Builds/Verification/BuildingKind-"+DateTime.UtcNow.Ticks);Directory.CreateDirectory(root);PlayerProfile.StorageOverride=Path.Combine(root,"profile.json");RegionCache.OverrideFolder=Path.Combine(root,"Regions");Application.logMessageReceived+=Warn;
                const string source="/private/tmp/RoadRushDetailCompiled/PantsideBuildingsV2";var pack=new DetailBuildingPack(source);var region=Fixture();region.Prepare();int added=pack.Apply(region);
                Debug.Log("BUILDING KIND COUNTS added="+added+" merged="+region.buildings.Length+" ordinary="+region.buildings.Count(b=>b.kind=="building")+" important="+region.buildings.Count(b=>b.kind=="important_building"));
                Check(added==410&&region.buildings.Length==403&&region.buildings.Count(b=>b.kind=="building")==396&&region.buildings.Count(b=>b.kind=="important_building")==7,"410approved candidates produce403unique outlines with396ordinary and7important classes");Check(region.buildings.All(b=>!b.measuredHeight),"relative derived heights never claim fabricated measured-height precision");Check(pack.Revision==2&&pack.RevisionSeries=="pantside-os-lidar"&&pack.Id=="pantside-os-lidar","actual compiler revision identity is read without inferring order from filenames");
                var data=JObject.Parse(File.ReadAllText(Path.Combine(source,"buildings.json")));var byId=((JArray)data["buildings"]).ToDictionary(t=>(string)t["id"]);bool exact=true;foreach(var b in region.buildings){var t=byId[b.id];exact&=b.points.Length==((JArray)t["points"]).Count&&b.height==(float)t["height"]&&b.kind==(string)t["kind"];for(int i=0;i<b.points.Length;i++){float x=(float)(((double)t["points"][i][0]-region.longitude)*111319.4908*Math.Cos(region.latitude*Math.PI/180)),z=(float)(((double)t["points"][i][1]-region.latitude)*111319.4908);exact&=b.points[i].x==x&&b.points[i].z==z;}}Check(exact,"bounded final footprint vertex order dimensions and source class are preserved exactly");
                var raw=(JArray)data["buildings"];int exactDuplicates=raw.Count(important=>(string)important["kind"]=="important_building"&&raw.Any(ordinary=>(string)ordinary["kind"]=="building"&&JToken.DeepEquals(important["points"],ordinary["points"])&&(float)important["height"]==(float)ordinary["height"]));
                Check(exactDuplicates==6&&region.buildings.Any(b=>b.id=="os-B3E7798E-E36C-4B3D-B20D-4941BC4E84CC-0"&&b.kind=="important_building"&&Math.Abs(b.height-10.76f)<.001f)&&!region.buildings.Any(b=>b.id=="os-1423F5B7-48DC-4B1D-AF86-E4C8A0C7095B-0"),"six exact cross-layer duplicates and one corresponding contained-part overlap retain important source outlines without double geometry");
                string reverseFolder=CopyPack(Path.Combine(root,"reverse-order"),source,(m,d)=>d["buildings"]=new JArray(((JArray)d["buildings"]).Reverse().Select(t=>t.DeepClone())));var reverse=Fixture();new DetailBuildingPack(reverseFolder).Apply(reverse);Check(JsonUtility.ToJson(new BuildingList{buildings=reverse.buildings})==JsonUtility.ToJson(new BuildingList{buildings=region.buildings}),"important class wins duplicates deterministically even when ordinary records occur later");
                string valid=WorldSnapshotCodec.CanonicalJson(region);var reloaded=WorldSnapshotCodec.Decode(valid,WorldSnapshotCodec.NetworkId(region),WorldSnapshotCodec.Epoch(region));Check(reloaded.buildings.Count(b=>b.kind=="important_building")==7&&reloaded.buildings.Count(b=>b.kind=="building")==396,"existing canonical snapshot format preserves approved source classes without schema additions");
                var legacy=new DetailBuildingPack("/private/tmp/RoadRushDetailCompiled/PantsideBuildings");var oldRegion=Fixture();oldRegion.Prepare();legacy.Apply(oldRegion);Check(oldRegion.buildings.Length>=400&&oldRegion.buildings.All(b=>b.kind=="residential"&&!b.measuredHeight),"single legacy pack retains its existing residential default and estimated heights");
                RejectedKind("unknown-kind",new JValue("school"));RejectedKind("overlong-kind",new JValue(new string('x',33)));RejectedKind("numeric-kind",new JValue(123));RejectedKind("object-kind",new JObject{{"kind","building"}});RejectedKind("null-kind",JValue.CreateNull());
                string missingLegacy=CopyPack(Path.Combine(root,"missing-legacy"),source,(m,d)=>{foreach(var t in (JArray)d["buildings"])((JObject)t).Remove("kind");});var missingRegion=Fixture();Check(new DetailBuildingPack(missingLegacy).ApplySafely(missingRegion)&&missingRegion.buildings.All(b=>b.kind=="residential"),"absent legacy class defaults to residential without changing geometry");
                string explicitLegacy=CopyPack(Path.Combine(root,"explicit-legacy"),source,(m,d)=>{foreach(var t in (JArray)d["buildings"])t["kind"]="residential";});var explicitRegion=Fixture();Check(new DetailBuildingPack(explicitLegacy).ApplySafely(explicitRegion)&&explicitRegion.buildings.All(b=>b.kind=="residential"),"explicit legacy residential class remains supported");
                string falsePrecision=CopyPack(Path.Combine(root,"false-precision"),source,(m,d)=>{foreach(var t in (JArray)d["buildings"])t["measuredHeight"]=true;});var precision=Fixture();new DetailBuildingPack(falsePrecision).Apply(precision);Check(precision.buildings.All(b=>!b.measuredHeight),"payload extras cannot elevate estimated heights to measured claims");
                string oldExplicit=CopyPack(Path.Combine(root,"zz-v1"),source,(m,d)=>m["revision"]=1);var first=new DetailBuildingPack(oldExplicit);Check(DetailBuildingPacks.SelectRevisions(new[]{pack,first}).Single().Identity==pack.Identity&&DetailBuildingPacks.SelectRevisions(new[]{first,pack}).Single().Identity==pack.Identity,"highest explicit revision wins independently of registration and hash order");
                Check(DetailBuildingPacks.SelectRevisions(new[]{legacy}).Single().Identity==legacy.Identity&&DetailBuildingPacks.SelectRevisions(new[]{legacy,pack}).Length==0,"single legacy remains usable but unorderable legacy/versioned coexistence fails closed");
                string collision=CopyPack(Path.Combine(root,"collision"),source,(m,d)=>m["attribution"]=(string)m["attribution"]+" conflicting record");Check(DetailBuildingPacks.SelectRevisions(new[]{pack,new DetailBuildingPack(collision)}).Length==0,"different content identities declaring the same revision fail closed");
                string series=CopyPack(Path.Combine(root,"series"),source,(m,d)=>{m["revision"]=3;m["revisionSeries"]="unrelated-series";});Check(DetailBuildingPacks.SelectRevisions(new[]{pack,new DetailBuildingPack(series)}).Length==0,"different revision series cannot silently replace each other");
                Check(DetailBuildingPacks.SelectRevisions(new[]{pack,pack}).Length==1,"duplicate identical immutable revisions deduplicate");
                Check(DetailBuildingPacks.CacheId("download-original",new[]{first})!=DetailBuildingPacks.CacheId("download-original",new[]{pack})&&RegionCache.Safe(DetailBuildingPacks.CacheId("download-"+new string('a',80),new[]{pack})),"selected exact manifest identity changes future cache with bounded filenames");Check(DetailBuildingPacks.CacheId("download-original",new[]{first,pack})==DetailBuildingPacks.CacheId("download-original",new[]{pack,first}),"cache identity is independent of caller enumeration order");
                string isolated=Path.Combine(root,"selection");CopyPack(Path.Combine(isolated,"older"),oldExplicit);CopyPack(Path.Combine(isolated,"newer"),source);var place=new WorldPlace{latitude=region.latitude,longitude=region.longitude,country_code="GB",size=3000};DetailBuildingPacks.OverrideRoot=isolated;string pinned=WorldSnapshotCodec.CanonicalJson(region);Check(DetailBuildingPacks.Find(place).Single().Identity==pack.Identity&&WorldSnapshotCodec.CanonicalJson(region)==pinned,"discovery selects future revision without mutating an already prepared snapshot");
                string invalidRevision=CopyPack(Path.Combine(root,"bad-revision"),source,(m,d)=>m["revision"]=0);bool rejected=false;try{new DetailBuildingPack(invalidRevision);}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid revision ordering metadata is rejected before selection");
                string moved=CopyPack(Path.Combine(isolated,"highest-outside"),source,(m,d)=>{m["revision"]=3;m["bounds"]=new JArray(-2,52,-1.9,52.1);d["buildings"]=new JArray();m["buildingCount"]=0;});Check(DetailBuildingPacks.Find(place).Length==0,"latest revision is selected before coverage filtering so stale in-area revision cannot reappear");
                File.WriteAllText("Builds/Verification/building-kind.txt",$"PASS {checks} classified kind transaction/legacy/revision/cache/canonical checks\n"+root+"\n");EditorApplication.Exit(0);
            }
            catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}
            finally{Application.logMessageReceived-=Warn;DetailBuildingPacks.OverrideRoot=null;}
        }
    }
}
